/**
 * IPAStatus
 *
 * How far an errand has got.
 *
 * While an agent is working out what to buy it reads as `qualifying`, `searching` or
 * `validating`. It then waits for the user: `pending_clarification` needs a question
 * answered, `pending_approval` needs the purchase approved. Once `approved` it may
 * sit in `monitoring` until the conditions it was given are met, and reads as
 * `executing` while the purchase is being made.
 *
 * `completed`, `failed`, `expired` and `cancelled` are final. An errand in one of
 * those four states will not change again, and can no longer be clarified or
 * cancelled.
 *
 * What may be done to an errand follows from where it has got to. Cancelling works
 * in any of the eight states that are not final. Answering questions works only
 * while the errand is actually waiting on some — `qualifying` or
 * `pending_clarification` — and is refused everywhere else, so its state is worth
 * reading before trying.
 */
export const zIpaStatus = z.enum([
    'qualifying',
    'searching',
    'validating',
    'pending_approval',
    'pending_clarification',
    'approved',
    'monitoring',
    'executing',
    'completed',
    'failed',
    'expired',
    'cancelled'
]).register(z.globalRegistry, {
    description: 'How far an errand has got.\n\nWhile an agent is working out what to buy it reads as `qualifying`, `searching` or\n`validating`. It then waits for the user: `pending_clarification` needs a question\nanswered, `pending_approval` needs the purchase approved. Once `approved` it may\nsit in `monitoring` until the conditions it was given are met, and reads as\n`executing` while the purchase is being made.\n\n`completed`, `failed`, `expired` and `cancelled` are final. An errand in one of\nthose four states will not change again, and can no longer be clarified or\ncancelled.\n\nWhat may be done to an errand follows from where it has got to. Cancelling works\nin any of the eight states that are not final. Answering questions works only\nwhile the errand is actually waiting on some — `qualifying` or\n`pending_clarification` — and is refused everywhere else, so its state is worth\nreading before trying.'
});

