/**
 * KnownChains
 *
 * EVM-compatible blockchain networks the codebase knows about.
 *
 * This is a *vocabulary* enum — the set of chain IDs the code can talk about
 * for asset metadata, off-ramp routing (Meld), payment-link acceptance, and
 * agent data lookups. It is NOT an acceptance enum: typing a request-model
 * field as `chain_id: KnownChains` does NOT gate input to operational chains.
 *
 * For write-boundary acceptance (onboarding, wallet creation, workflow
 * contracts), use `DeployableChain` from `sumvin/model/enums/chain.py`.
 *
 * Chain ID values follow the EIP-155 standard.
 *
 * - `1` - Ethereum Mainnet
 * - `10` - Optimism
 * - `137` - Polygon (formerly Matic)
 * - `42161` - Arbitrum One
 * - `8453` - Base
 * - `43114` - Avalanche C-Chain
 * - `56` - BNB Smart Chain (BSC)
 * - `1328` - Sei Testnet
 * - `1329` - Sei
 */
export const zKnownChains = z.union([
    z.literal(1),
    z.literal(10),
    z.literal(137),
    z.literal(42161),
    z.literal(8453),
    z.literal(43114),
    z.literal(56),
    z.literal(1328),
    z.literal(1329)
]).register(z.globalRegistry, {
    description: 'EVM-compatible blockchain networks the codebase knows about.\n\nThis is a *vocabulary* enum — the set of chain IDs the code can talk about\nfor asset metadata, off-ramp routing (Meld), payment-link acceptance, and\nagent data lookups. It is NOT an acceptance enum: typing a request-model\nfield as `chain_id: KnownChains` does NOT gate input to operational chains.\n\nFor write-boundary acceptance (onboarding, wallet creation, workflow\ncontracts), use `DeployableChain` from `sumvin/model/enums/chain.py`.\n\nChain ID values follow the EIP-155 standard.\n\n- `1` - Ethereum Mainnet\n- `10` - Optimism\n- `137` - Polygon (formerly Matic)\n- `42161` - Arbitrum One\n- `8453` - Base\n- `43114` - Avalanche C-Chain\n- `56` - BNB Smart Chain (BSC)\n- `1328` - Sei Testnet\n- `1329` - Sei'
});

/**
 * KycSessionOrigin
 *
 * Where a person began verification, and therefore where they return to
 * once it finishes: a terminal, a conversation with an assistant, or the
 * Sumvin app they already had open.
 *
 * The completion screen has nothing else to go on — "return to your terminal"
 * and "return to your conversation" are different things to tell someone, and
 * only this fact separates them.
 */
export const zKycSessionOrigin = z.enum([
    'cli',
    'connector',
    'app'
]).register(z.globalRegistry, {
    description: 'Where a person began verification, and therefore where they return to\nonce it finishes: a terminal, a conversation with an assistant, or the\nSumvin app they already had open.\n\nThe completion screen has nothing else to go on — "return to your terminal"\nand "return to your conversation" are different things to tell someone, and\nonly this fact separates them.'
});

/**
 * Link
 *
 * HAL-style hypermedia link for resource navigation and actions.
 *
 * Links enable clients to discover available actions and navigate related resources
 * without hardcoding URLs. Action links include the HTTP method to use.
 */
export const zLink = z.object({
    href: z.string().register(z.globalRegistry, {
        description: 'URL to the linked resource or action endpoint.'
    }),
    method: z.string().register(z.globalRegistry, {
        description: 'HTTP method to use when following this link. GET for navigation, POST/PUT/DELETE for actions.'
    }).optional().default('GET'),
    templated: z.boolean().register(z.globalRegistry, {
        description: 'If true, href contains URI template variables (e.g., {id}) that must be substituted.'
    }).optional().default(false),
    description: z.string().nullish()
}).register(z.globalRegistry, {
    description: 'HAL-style hypermedia link for resource navigation and actions.\n\nLinks enable clients to discover available actions and navigate related resources\nwithout hardcoding URLs. Action links include the HTTP method to use.'
});

