/**
 * MandateLimitStatus
 *
 * Whether a mandate carries a spend limit, and whether what is left under it is known.
 *
 * `no_amount_authorized` — the mandate authorizes no amount, so there is no limit to
 * report and nothing to measure spending in flight against.
 *
 * `headroom_unknown` — a limit is in force, but some spending against it could not be
 * read, or could not be compared against that limit: either spending still in flight,
 * or what has already settled. How much is still available cannot be worked out, and
 * the amounts consumed and reserved are each a minimum rather than a whole.
 *
 * `headroom_known` — a limit is in force and every amount spent against it was
 * counted, so the amount still available is a figure spending can be planned against.
 *
 * None of the three permits unlimited spending: a purchase is checked against the
 * mandate when it is made, whatever this reports.
 */
export const zMandateLimitStatus = z.enum([
    'no_amount_authorized',
    'headroom_unknown',
    'headroom_known'
]).register(z.globalRegistry, {
    description: 'Whether a mandate carries a spend limit, and whether what is left under it is known.\n\n`no_amount_authorized` — the mandate authorizes no amount, so there is no limit to\nreport and nothing to measure spending in flight against.\n\n`headroom_unknown` — a limit is in force, but some spending against it could not be\nread, or could not be compared against that limit: either spending still in flight,\nor what has already settled. How much is still available cannot be worked out, and\nthe amounts consumed and reserved are each a minimum rather than a whole.\n\n`headroom_known` — a limit is in force and every amount spent against it was\ncounted, so the amount still available is a figure spending can be planned against.\n\nNone of the three permits unlimited spending: a purchase is checked against the\nmandate when it is made, whatever this reports.'
});

