/**
 * PintStatus
 *
 * How far a purchase-intent token has got.
 *
 * Only an `active` token can authorise spending. `pending` has been prepared but is
 * not yet signed and cannot authorise anything. `consumed` has already been spent
 * against, `revoked` was withdrawn, and `expired` passed its expiry — none of the
 * three can authorise a purchase, and none of them return to `active`.
 */
export const zPintStatus = z.enum([
    'pending',
    'active',
    'consumed',
    'revoked',
    'expired'
]).register(z.globalRegistry, {
    description: 'How far a purchase-intent token has got.\n\nOnly an `active` token can authorise spending. `pending` has been prepared but is\nnot yet signed and cannot authorise anything. `consumed` has already been spent\nagainst, `revoked` was withdrawn, and `expired` passed its expiry — none of the\nthree can authorise a purchase, and none of them return to `active`.'
});

