/**
 * SignerRole
 *
 * What a `UserWallet` row exists to sign for, when it exists to sign at all.
 *
 * Deliberately a one-member set. `UserWallet` already carries the facts a
 * richer set would restate: `signer_id` names the agent signer a row belongs
 * to, and `is_eoa` separates an externally-owned account from a Safe. Adding
 * `SAFE` or `USER_EOA` members here would duplicate those with nothing keeping
 * the copies in sync, so the only value is the one this column was introduced
 * to record.
 *
 * NULL is not a member and does not mean "not a mandate key" — it means the
 * row predates the column and nobody has classified it. A read that must find
 * mandate keys filters for `CLI_MANDATE_KEY` explicitly rather than treating
 * the absence of a value as an answer.
 */
export const zSignerRole = z.enum(['cli_mandate_key']).register(z.globalRegistry, {
    description: 'What a `UserWallet` row exists to sign for, when it exists to sign at all.\n\nDeliberately a one-member set. `UserWallet` already carries the facts a\nricher set would restate: `signer_id` names the agent signer a row belongs\nto, and `is_eoa` separates an externally-owned account from a Safe. Adding\n`SAFE` or `USER_EOA` members here would duplicate those with nothing keeping\nthe copies in sync, so the only value is the one this column was introduced\nto record.\n\nNULL is not a member and does not mean "not a mandate key" — it means the\nrow predates the column and nobody has classified it. A read that must find\nmandate keys filters for `CLI_MANDATE_KEY` explicitly rather than treating\nthe absence of a value as an answer.'
});

