/**
 * TransactionStatus
 *
 * Lifecycle state of a transaction.
 *
 * **State progression:** `pending` → `processing` → `completed` | `failed` | `cancelled`
 *
 * - `pending` - Transaction created but not yet submitted for processing
 * - `processing` - Submitted to network/provider, awaiting confirmation
 * - `completed` - Successfully finalized (on-chain confirmed or bank settled)
 * - `failed` - Transaction rejected or reverted (check error details)
 * - `cancelled` - User or system cancelled before completion
 */
export const zTransactionStatus = z.enum([
    'pending',
    'processing',
    'completed',
    'failed',
    'cancelled'
]).register(z.globalRegistry, {
    description: 'Lifecycle state of a transaction.\n\n**State progression:** `pending` → `processing` → `completed` | `failed` | `cancelled`\n\n- `pending` - Transaction created but not yet submitted for processing\n- `processing` - Submitted to network/provider, awaiting confirmation\n- `completed` - Successfully finalized (on-chain confirmed or bank settled)\n- `failed` - Transaction rejected or reverted (check error details)\n- `cancelled` - User or system cancelled before completion'
});

