/**
 * TransactionType
 *
 * Classification of financial transaction types.
 *
 * **Crypto/Wallet transactions:**
 * - `deposit` - Incoming transfer to user's wallet from external source
 * - `withdrawal` - Outgoing transfer from user's wallet to external address
 * - `transfer` - Internal movement between user's own wallets
 * - `swap` - Token exchange (e.g., ETH → USDC)
 * - `on_ramp` - Fiat-to-crypto conversion via exchange/provider
 * - `off_ramp` - Crypto-to-fiat conversion via exchange/provider
 *
 * **Card transactions:**
 * - `card_purchase` - Debit card spend at merchant
 * - `card_refund` - Merchant-initiated refund to card
 *
 * **Bank account transactions:**
 * - `bank_transfer` - ACH/wire transfer between accounts
 * - `direct_debit` - Recurring automated payment (bills, subscriptions)
 * - `standing_order` - Scheduled fixed payment
 * - `bank_payment` - One-time outgoing payment
 * - `bank_refund` - Return of funds to bank account
 * - `interest` - Interest credit on savings/checking account
 * - `fee` - Bank service charge or maintenance fee
 */
export const zTransactionType = z.enum([
    'deposit',
    'withdrawal',
    'transfer',
    'swap',
    'card_purchase',
    'card_refund',
    'on_ramp',
    'off_ramp',
    'bank_transfer',
    'direct_debit',
    'standing_order',
    'bank_payment',
    'bank_refund',
    'interest',
    'fee'
]).register(z.globalRegistry, {
    description: 'Classification of financial transaction types.\n\n**Crypto/Wallet transactions:**\n- `deposit` - Incoming transfer to user\'s wallet from external source\n- `withdrawal` - Outgoing transfer from user\'s wallet to external address\n- `transfer` - Internal movement between user\'s own wallets\n- `swap` - Token exchange (e.g., ETH → USDC)\n- `on_ramp` - Fiat-to-crypto conversion via exchange/provider\n- `off_ramp` - Crypto-to-fiat conversion via exchange/provider\n\n**Card transactions:**\n- `card_purchase` - Debit card spend at merchant\n- `card_refund` - Merchant-initiated refund to card\n\n**Bank account transactions:**\n- `bank_transfer` - ACH/wire transfer between accounts\n- `direct_debit` - Recurring automated payment (bills, subscriptions)\n- `standing_order` - Scheduled fixed payment\n- `bank_payment` - One-time outgoing payment\n- `bank_refund` - Return of funds to bank account\n- `interest` - Interest credit on savings/checking account\n- `fee` - Bank service charge or maintenance fee'
});

