/**
 * WalletSignerRegistrationLinks
 *
 * Links on an accepted signer registration.
 *
 * The registration answers before the owner addition has happened, so the
 * link that matters is the one that says where the outcome will appear.
 * `signer-status` is a separate rel from `self` on purpose: `self` is the
 * collection the request was posted to, and following it again would start a
 * second registration rather than read the first one's result.
 */
export const zWalletSignerRegistrationLinks = z.object({
    self: zLink,
    'signer-status': zLink.nullish(),
    wallet: zLink.nullish()
}).register(z.globalRegistry, {
    description: 'Links on an accepted signer registration.\n\nThe registration answers before the owner addition has happened, so the\nlink that matters is the one that says where the outcome will appear.\n`signer-status` is a separate rel from `self` on purpose: `self` is the\ncollection the request was posted to, and following it again would start a\nsecond registration rather than read the first one\'s result.'
});

