/**
 * X402Scheme
 *
 * Payment scheme carried in an x402 challenge or signature envelope.
 */
export const zX402Scheme = z.enum(['exact']).register(z.globalRegistry, {
    description: 'Payment scheme carried in an x402 challenge or signature envelope.'
});

/**
 * X402PaymentRequirements
 *
 * One acceptable way a payer may settle a given payment request.
 *
 * The 402 challenge body lists one entry per supported chain and asset.
 * Agents pick one entry, build the corresponding signed payload, and
 * retry the original URL with the ``PAYMENT-SIGNATURE`` header.
 */
export const zX402PaymentRequirements = z.object({
    scheme: zX402Scheme,
    network: z.string().regex(/^eip155:\d+$/).register(z.globalRegistry, {
        description: 'CAIP-2 network identifier for the chain on which settlement must occur (e.g. ``eip155:1329`` for Sei).'
    }),
    maxAmountRequired: z.string().register(z.globalRegistry, {
        description: 'Maximum amount the payer must authorize, expressed as a stringified integer in the asset\'s smallest unit (e.g. micro-USDC).'
    }),
    resource: z.string().register(z.globalRegistry, {
        description: 'Canonical URL that these requirements gate.'
    }),
    description: z.string().nullish(),
    mimeType: z.string().register(z.globalRegistry, {
        description: 'Media type of the resource protected by these requirements.'
    }).optional().default('application/json'),
    payTo: z.string().register(z.globalRegistry, {
        description: 'Destination wallet address the payer must settle to.'
    }),
    maxTimeoutSeconds: z.int().register(z.globalRegistry, {
        description: 'Maximum number of seconds the payer may take to submit a valid signed payload before these requirements expire.'
    }),
    asset: z.string().register(z.globalRegistry, {
        description: 'Asset identifier. For EVM networks this is the ERC-20 contract address; for non-EVM networks it is a chain-native asset identifier.'
    }),
    outputSchema: z.record(z.string(), z.unknown()).nullish(),
    extra: z.record(z.string(), z.unknown()).nullish()
}).register(z.globalRegistry, {
    description: 'One acceptable way a payer may settle a given payment request.\n\nThe 402 challenge body lists one entry per supported chain and asset.\nAgents pick one entry, build the corresponding signed payload, and\nretry the original URL with the ``PAYMENT-SIGNATURE`` header.'
});

/**
 * X402PaymentRequired
 *
 * Body of a ``402 Payment Required`` response under the x402 protocol.
 */
export const zX402PaymentRequired = z.object({
    x402Version: z.int().register(z.globalRegistry, {
        description: 'x402 protocol version supported by this response.'
    }).optional().default(2),
    error: z.string().nullish(),
    accepts: z.array(zX402PaymentRequirements).min(1).register(z.globalRegistry, {
        description: 'Ordered list of payment requirements the payer may choose from.'
    }),
    extensions: z.record(z.string(), z.unknown()).nullish()
}).register(z.globalRegistry, {
    description: 'Body of a ``402 Payment Required`` response under the x402 protocol.'
});

